tests/image_deps_test.sh.text:
#!/bin/bash
# The production image must contain every vendor tool that lib/ uses at runtime.
bash scripts/build-image.sh >/dev/null || exit 1
for d in $(grep -rhoE 'vendor/[a-z0-9_-]+' lib bin | sort -u); do
  [ -d "build/image/$d" ] || { echo "image_deps: $d used by lib/bin but missing from image"; exit 1; }
done
out=$(APP_ROOT=build/image bash build/image/bin/app avatar me.png)
[ "$out" = "status=201 avatar=me-256.png" ] || { echo "image_deps: avatar in image: $out"; exit 1; }

